(7289933, 1136538, 68504, '<td valign="top">a pleasure to celebrate.</td>', 'a pleasure to celebrate.', '2014-12-04 20:46:43.000000', NULL, 1),
(7289967, 1136525, 177322, '<td valign="top">So intrigued I am by the orderliness, I actually found the meal secondary, but the clarity and the arrangement of the subject material within the frame is really quite impressive. Quite a fascinating glimpse into a very personal work space.  The incongruity of the food in such an organized space is a perfect response to this challenge.  Love the pedestal for the monitor - a ream of paper. Wish you well. Is that really rice with stuffing?</td>', 'So intrigued I am by the orderliness, I actually found the meal secondary, but the clarity and the arrangement of the subject material within the frame is really quite impressive. Quite a fascinating glimpse into a very personal work space.  The incongruity of the food in such an organized space is a perfect response to this challenge.  Love the pedestal for the monitor - a ream of paper. Wish you well. Is that really rice with stuffing?', '2014-12-04 22:04:28.000000', NULL, 1),
(7290185, 1136188, 138253, '<td valign="top">Zing!<br/>Love it!</td>', 'Zing!Love it!', '2014-12-05 15:30:27.000000', NULL, 1),
