(7290519, 1136188, 129147, '<td valign="top">.</td>', '.', '2014-12-07 01:53:35.000000', NULL, 1),
(7291011, 1136525, 170281, '<td valign="top">I have been in the same boat and have employees overseas that also had to work on Thanksgiving.  I can sympathize.</td>', 'I have been in the same boat and have employees overseas that also had to work on Thanksgiving.  I can sympathize.', '2014-12-07 22:12:24.000000', NULL, 1),
(7291219, 1136510, 12611, '<td valign="top">I would eat Japanese for Thanksgiving, but no one else would join me... Nice slice of life.</td>', 'I would eat Japanese for Thanksgiving, but no one else would join me... Nice slice of life.', '2014-12-08 09:46:58.000000', NULL, 1),
