(7291259, 1136523, 135744, '<td valign="top">I find the photo a bit ugly though I am sure the food was delicious</td>', 'I find the photo a bit ugly though I am sure the food was delicious', '2014-12-08 10:44:43.000000', NULL, 1),
(7291260, 1136555, 135744, '<td valign="top">The smile makes this photo in my opinion. I also like how the beer is called "Magic Hat" and there is quite a hat on the person bottom left. The poor bloke on the top left nearly didn''t get into the photo.</td>', 'The smile makes this photo in my opinion. I also like how the beer is called "Magic Hat" and there is quite a hat on the person bottom left. The poor bloke on the top left nearly didn''t get into the photo.', '2014-12-08 10:46:53.000000', NULL, 1),
(7291261, 1136529, 135744, '<td valign="top">Would have liked to see more of the cake in focus but nicely lit photo</td>', 'Would have liked to see more of the cake in focus but nicely lit photo', '2014-12-08 10:47:30.000000', NULL, 1),
