(7291673, 1136531, 13077, '<td valign="top">Looks very tasty and cooked just right. Good lighting and background of the photo.</td>', 'Looks very tasty and cooked just right. Good lighting and background of the photo.', '2014-12-09 18:30:26.000000', NULL, 1),
(7291674, 1136555, 13077, '<td valign="top">Has a casual and carefree vibe, looks like a fun meal.</td>', 'Has a casual and carefree vibe, looks like a fun meal.', '2014-12-09 18:31:01.000000', NULL, 1),
(7291675, 1136505, 13077, '<td valign="top">Is the title what this is called? It does look pretty tasty.</td>', 'Is the title what this is called? It does look pretty tasty.', '2014-12-09 18:31:36.000000', NULL, 1),
(7291677, 1136358, 13077, '<td valign="top">A nice candid shot, well exposed for the subjects and not too blown out (although some may disagree) in the background.</td>', 'A nice candid shot, well exposed for the subjects and not too blown out (although some may disagree) in the background.', '2014-12-09 18:32:19.000000', NULL, 1),
(7291679, 1136542, 13077, '<td valign="top">Nicely arranged and good light. Although seafood''s not my favorite it looks very appetizing.</td>', 'Nicely arranged and good light. Although seafood''s not my favorite it looks very appetizing.', '2014-12-09 18:33:16.000000', NULL, 1),
(7291680, 1136536, 13077, '<td valign="top">Interesting choice to have so many white tones, but the rest does a pretty good job defining edges and there is enough detail. Still, I think it would stand out more on a different colored background.</td>', 'Interesting choice to have so many white tones, but the rest does a pretty good job defining edges and there is enough detail. Still, I think it would stand out more on a different colored background.', '2014-12-09 18:34:45.000000', NULL, 1),
(7291681, 1136510, 13077, '<td valign="top">Mmm.</td>', 'Mmm.', '2014-12-09 18:35:21.000000', NULL, 1),
(7291682, 1136499, 13077, '<td valign="top">Heck, I would be too, that looks good.</td>', 'Heck, I would be too, that looks good.', '2014-12-09 18:35:36.000000', NULL, 1),
(7291683, 1136248, 13077, '<td valign="top">Oh wow. Cool project, and good light and composition when shooting it.</td>', 'Oh wow. Cool project, and good light and composition when shooting it.', '2014-12-09 18:36:03.000000', NULL, 1),
(7291684, 1136317, 13077, '<td valign="top">Very busy but full of interesting details. The very wide view works well here.</td>', 'Very busy but full of interesting details. The very wide view works well here.', '2014-12-09 18:36:48.000000', NULL, 1),
(7291685, 1136229, 13077, '<td valign="top">Probably not the photo I would have chosen to enter if there were any others shot around that time. The composition and timing feel awkward, also there is a lot of grain.</td>', 'Probably not the photo I would have chosen to enter if there were any others shot around that time. The composition and timing feel awkward, also there is a lot of grain.', '2014-12-09 18:38:05.000000', NULL, 1),
(7291686, 1136157, 13077, '<td valign="top">Looks good. A nice candid, will be a good photo to remember the day by.</td>', 'Looks good. A nice candid, will be a good photo to remember the day by.', '2014-12-09 18:38:41.000000', NULL, 1),
(7291687, 1136534, 13077, '<td valign="top">The dog sure is thankful!</td>', 'The dog sure is thankful!', '2014-12-09 18:38:59.000000', NULL, 1),
(7291688, 1136553, 13077, '<td valign="top">Hmm... I''d probably rather eat it before they got to it.</td>', 'Hmm... I''d probably rather eat it before they got to it.', '2014-12-09 18:39:46.000000', NULL, 1),
(7291689, 1136529, 13077, '<td valign="top">The contrast between the tablecloth and plate/pie/fork is nice, but I think slightly deeper DOF would have worked better.</td>', 'The contrast between the tablecloth and plate/pie/fork is nice, but I think slightly deeper DOF would have worked better.', '2014-12-09 18:40:35.000000', NULL, 1),
(7291690, 1136525, 13077, '<td valign="top">Somebody''s got to do it, so thank you.</td>', 'Somebody''s got to do it, so thank you.', '2014-12-09 18:41:01.000000', NULL, 1),
(7291691, 1136551, 13077, '<td valign="top">Nice and classy looking setup.</td>', 'Nice and classy looking setup.', '2014-12-09 18:41:14.000000', NULL, 1),
(7291692, 1136221, 13077, '<td valign="top">Is it the feathers of a bird that was plucked and cooked?</td>', 'Is it the feathers of a bird that was plucked and cooked?', '2014-12-09 18:41:55.000000', NULL, 1),
(7291693, 1136250, 13077, '<td valign="top">The photo would have been nicer if the man was either shown including his face or not in the frame in my opinion. But the food looks tasty.</td>', 'The photo would have been nicer if the man was either shown including his face or not in the frame in my opinion. But the food looks tasty.', '2014-12-09 18:42:35.000000', NULL, 1),
(7291694, 1136518, 13077, '<td valign="top">Nice - good arrangement and nicely lit to show texture in the meat well.</td>', 'Nice - good arrangement and nicely lit to show texture in the meat well.', '2014-12-09 18:43:05.000000', NULL, 1),
(7291695, 1136523, 13077, '<td valign="top">Sounds good.</td>', 'Sounds good.', '2014-12-09 18:43:15.000000', NULL, 1),
(7291696, 1136121, 13077, '<td valign="top">Nice - the high-key look works pretty well in this one, but I think the composition might have been improved on by trying different positions. Not sure which angle would look best, but having the dish partly cropped out is distracting.</td>', 'Nice - the high-key look works pretty well in this one, but I think the composition might have been improved on by trying different positions. Not sure which angle would look best, but having the dish partly cropped out is distracting.', '2014-12-09 18:44:24.000000', NULL, 1),
(7291697, 1136550, 13077, '<td valign="top">Nicely decorated pie. Good shot with just enough DOF and a nice clean background that all goes with the theme well.</td>', 'Nicely decorated pie. Good shot with just enough DOF and a nice clean background that all goes with the theme well.', '2014-12-09 18:44:59.000000', NULL, 1),
(7291698, 1136188, 13077, '<td valign="top">lol. well played.</td>', 'lol. well played.', '2014-12-09 18:45:19.000000', NULL, 1),
(7291699, 1136339, 13077, '<td valign="top">Nice and colorful, well shot and good use of shallow DOF.</td>', 'Nice and colorful, well shot and good use of shallow DOF.', '2014-12-09 18:49:09.000000', NULL, 1),
(7291700, 1136207, 13077, '<td valign="top">Hope you went back for seconds, that looks a bit small for a feast. I like the processing style of this one.</td>', 'Hope you went back for seconds, that looks a bit small for a feast. I like the processing style of this one.', '2014-12-09 18:50:00.000000', NULL, 1),
(7291702, 1136195, 13077, '<td valign="top">A little too close-up for my taste, also a bit soft.</td>', 'A little too close-up for my taste, also a bit soft.', '2014-12-09 18:53:44.000000', NULL, 1),
(7291703, 1136224, 13077, '<td valign="top">Nice point of view and well composed. A bit soft but not necessarily a bad thing.</td>', 'Nice point of view and well composed. A bit soft but not necessarily a bad thing.', '2014-12-09 18:54:11.000000', NULL, 1),
(7291704, 1136554, 13077, '<td valign="top">I think a little bit wider angle shot would have worked better. The things at the top and bottom that are cropped off might have been better either left out or included all the way.</td>', 'I think a little bit wider angle shot would have worked better. The things at the top and bottom that are cropped off might have been better either left out or included all the way.', '2014-12-09 18:55:01.000000', NULL, 1),
